									jQuery('div.dW_content div.dW_membres div.dW_membre:not([data-index="' + _new_index + '"])', _sectionElt)
										.removeClass('dW_generic__open')
									;
									jQuery('div.dW_content div.dW_membres div.dW_membre[data-index="' + _new_index + '"]', _sectionElt)
										.addClass('dW_generic__open')
									;
